         ensures
             match result {
                 Ok(a) => a@ == raw_addr as int,
                 Err(e) => e.code == crate::error::ErrorCode::BadAddress,
             },
     )]
     fn from_raw_value(raw_addr: usize) -> Result<Self, Error>;

     #[verus_spec(result =>
